package com.example.partnerintegrationmock.application;
import com.example.partnerintegrationmock.integration.AppointmentCallbackClient; import com.example.partnerintegrationmock.model.MockBooking; import org.junit.jupiter.api.Test; import java.util.*; import java.util.concurrent.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class MockBookingServiceTest { @Test void submissionIsIdempotentAndConfirmationCompletionCallAppointment(){var client=mock(AppointmentCallbackClient.class);var service=new MockBookingService(client);var id=UUID.randomUUID();var b=service.submit(id,"V","D","Dealer","S","OIL");assertEquals(b.partnerRequestReference,service.submit(id,"V","D","Dealer","S","OIL").partnerRequestReference);assertNull(b.externalDmsReference);var confirmed=service.confirm(b.partnerRequestReference);assertEquals(MockBooking.State.CONFIRMED,confirmed.state);verify(client).confirm(id,confirmed.externalDmsReference);var completed=service.complete(b.partnerRequestReference);assertEquals(MockBooking.State.COMPLETED,completed.state);verify(client).complete(id,confirmed.externalDmsReference);}
@Test void rejectsConflictingAndPrematureCompletion(){var service=new MockBookingService(mock(AppointmentCallbackClient.class));var id=UUID.randomUUID();var b=service.submit(id,"V","D","Dealer","S","OIL");assertThrows(MockBookingService.Conflict.class,()->service.submit(id,"DIFFERENT","D","Dealer","S","OIL"));assertThrows(MockBookingService.Conflict.class,()->service.complete(b.partnerRequestReference));}
@Test void failedConfirmationReservesReferenceAndRetriesSameCallback(){var client=mock(AppointmentCallbackClient.class); doThrow(new RuntimeException("timeout")).doNothing().when(client).confirm(any(),any()); var service=new MockBookingService(client); var b=service.submit(UUID.randomUUID(),"V","D","Dealer","S","OIL"); var first=service.confirm(b.partnerRequestReference); assertEquals(MockBooking.Delivery.FAILED,first.confirmCallbackState); var reference=first.externalDmsReference; var retried=service.confirm(b.partnerRequestReference); assertEquals(MockBooking.State.CONFIRMED,retried.state); assertEquals(reference,retried.externalDmsReference); verify(client,times(2)).confirm(eq(b.appointmentId),eq(reference)); }
@Test void repeatedDeliveredActionsAreNoOps(){var client=mock(AppointmentCallbackClient.class);var service=new MockBookingService(client);var b=service.submit(UUID.randomUUID(),"V","D","Dealer","S","OIL");service.confirm(b.partnerRequestReference);service.confirm(b.partnerRequestReference);service.complete(b.partnerRequestReference);service.complete(b.partnerRequestReference);verify(client,times(1)).confirm(any(),any());verify(client,times(1)).complete(any(),any());}
@Test void concurrentIdenticalSubmissionsAndConfirmationHaveOneBusinessEffect() throws Exception {var client=mock(AppointmentCallbackClient.class);var service=new MockBookingService(client);var id=UUID.randomUUID();var pool=Executors.newFixedThreadPool(8);var tasks=new ArrayList<Callable<String>>();for(int i=0;i<8;i++)tasks.add(()->service.submit(id,"V","D","Dealer","S","OIL").partnerRequestReference);var refs=new HashSet<String>();for(var f:pool.invokeAll(tasks))refs.add(f.get());assertEquals(1,refs.size());var ref=refs.iterator().next();var confirms=new ArrayList<Callable<MockBooking>>();for(int i=0;i<8;i++)confirms.add(()->service.confirm(ref));for(var f:pool.invokeAll(confirms))assertEquals(MockBooking.State.CONFIRMED,f.get().state);pool.shutdown();verify(client,times(1)).confirm(any(),any());}
}
